import { test, expect } from '@playwright/test';

test.describe('Date Picker Keyboard Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should open date picker with keyboard', async ({ page }) => {
    await page.getByRole('textbox', { name: /date/i }).focus();
    await page.keyboard.press('Enter');
    const datePicker = page.getByRole('dialog', { name: /select date/i });
    await expect(datePicker).toBeVisible();
  });

  test('should navigate and select date using keyboard', async ({ page }) => {
    await page.getByRole('textbox', { name: /date/i }).focus();
    await page.keyboard.press('Enter');
    const datePicker = page.getByRole('dialog', { name: /select date/i });
    await expect(datePicker).toBeVisible();

    await page.keyboard.press('ArrowRight');
    await page.keyboard.press('ArrowRight');
    await page.keyboard.press('Enter'); // Assuming the second date is selected
    await expect(page.getByRole('textbox', { name: /date/i })).toHaveValue('2023-10-15'); // Replace with the expected date
  });
});
